package com.mhtextractor.uiport;

/**
 * 工作区命令（P3-3a 最小切片起，B3 扩至勾选与分组命令集，B4 扩至参数命令族，B5-1 扩至导入编排，
 * B6 扩至提取任务通道）：
 * 撤销、清场、勾选（{@code setChecked}）、分组（{@code group/ungroup/renameGroup}）、
 * 展开状态（{@code toggleGroupExpanded}）、参数应用/清除
 * （{@code setGlobalParams/setGroupParams/setItemParams/clearParams/applyGlobalParams}）、
 * 导入编排（{@code importPaths/applyImportPlan}）与提取任务通道
 * （{@code startExtraction/cancelExtraction}）。
 *
 * <p>命令语义由后端保证（数据序 / 分组关系 / 勾选 / 展开状态 / 撤销命令的唯一所有者是后端模型）；
 * 命令生效后经 {@link PortEvents} 推送变更事件，前端据此刷新投影。B3 的勾选 / 组名 /
 * 展开写入是<b>静默</b>的（不发布事件）：它们不改变数据序/结构，投影刷新由前端
 * 在命令返回后显式重建（GUI 的抽屉动画在动画起始帧重建显示序）。B4 的参数命令
 * 是<b>事件驱动</b>的：后端完成「写入 + 撤销压栈 + 磁盘缓存失效」后发布
 * {@link PortEvent.ParamStateChanged}，前端按事件执行列表 / 参数色刷新。</p>
 *
 * <p>后台活动代际、预解析和预览加载由应用层持有。</p>
 */
public interface WorkspaceCommands {

    void cancelWorkspaceActivity();
    void cancelPreviewLoad();
    void startPreparse();
    void startPreparseFor(java.util.List<String> paths);
    void refreshPreparseProgress();
    void loadPreview(String path, boolean largeFileConfirmed);
    void resolvePreviewRegion(long generation, String path, boolean accepted);
    void awaitPreviewInFlight(long millis);

    // ---- B3：勾选命令 + 分组命令集（处置项 6 / 5）----

    /**
     * 勾选写入 —— 提取输入事实的<b>唯一写入口</b>：按路径解析条目并批量写入
     * （路径是导入去重后的唯一键）。
     *
     * <p><b>静默写入</b>：不触发任何变更事件 / 滚动 / 焦点；未知路径<b>静默跳过</b>。
     * 三态（{@link TriState}）由查询 {@code workspace().selection()} 按当前勾选事实导出。</p>
     */
    void setChecked(java.util.List<String> paths, boolean checked);

    /** 建组：按路径解析条目（保持入参顺序）合并为一个新组；组名唯一化由后端保证。目标为空或均不可解析时为 no-op。 */
    void group(java.util.List<String> paths, String namePrefix);

    /** 拆分组：组从顶层移除，成员按原组内顺序插回原位置（组参数下发为成员条目级参数）；组不存在时为 no-op。 */
    void ungroup(long groupNo);

    /** 组改名：新名按后端组名集合唯一化后写入并永久退出「未命名组」提醒；组不存在时为 no-op。 */
    void renameGroup(long groupNo, String newName);

    /**
     * 折叠/展开翻转（幂等）：每调用恰好翻转一次展开标志 —— 状态由后端持有并按其当前值原子翻转，
     * 调用方不传目标值；快速连续调用（双击连点）=「翻过去再翻回来」，不会基于陈旧读数
     * 重复应用同一目标值。组不存在时为 no-op。
     */
    void toggleGroupExpanded(long groupNo);

    // ---- B4：参数命令族（处置项 3 / 4）----

    /**
     * 全局参数确认写入（{@code applyConfirmedParams} 语义）：整体替换当前模式已确认参数缓存，
     * 压一条 PARAM_SET 撤销记录（批量应用期间经剪贴板累积为整批一条），失效全部条目磁盘缓存
     * （规则 a），并发布 {@code ParamStateChanged(SET_GLOBAL, 全部条目路径)}。
     */
    void setGlobalParams(boolean imageMode, com.mhtextractor.model.AppConfig params);

    /**
     * 组参数写入（{@code applyGroupParams} 语义）：写入该组当前模式参数缓存，压 PARAM_SET
     * 撤销记录，失效该组未移除成员的磁盘缓存，并发布 {@code ParamStateChanged(SET_GROUP, 成员路径)}。
     * 组不存在时为 no-op（不发布事件、不压撤销记录）。
     */
    void setGroupParams(long groupNo, boolean imageMode, com.mhtextractor.model.AppConfig params);

    /**
     * 条目级参数写入（{@code applyItemParams} 语义）：写入该条目当前模式条目级参数，压 PARAM_SET
     * 撤销记录，失效该条目磁盘缓存，并发布 {@code ParamStateChanged(SET_ITEM, [路径])}。
     * 路径不存在时静默跳过（不发布事件、不压撤销记录）。
     */
    void setItemParams(String path, boolean imageMode, com.mhtextractor.model.AppConfig params);

    /**
     * 清除参数（{@code clearParamsForTargets} 语义）：<b>勾选优先</b> —— 后端按当前勾选事实
     * （可见条目）解析实际作用集合，勾选为空时回退到 {@code fallbackTargets}（右键命中 /
     * 当前选中的条目或组）；无参数目标自然跳过；一次操作一条 CLEAR_PARAMS 撤销记录
     * （before 快照，一次撤销全部恢复）。发布 {@code ParamStateChanged(CLEAR, 受影响条目路径)}；
     * 无任何可清除目标时为 no-op（不发布事件、不压撤销记录）。
     */
    void clearParams(java.util.List<TargetId> fallbackTargets, boolean imageMode);

    /**
     * 应用到全局（{@code applyGlobalParamsTo} 语义）：把目标（条目或组）的生效参数写入当前模式
     * 全局缓存，并清空当前模式全部独立参数（条目级 + 组，含目标自身），另一模式不受影响；
     * 压一条 APPLY_GLOBAL 撤销记录（应用前完整参数快照）。发布
     * {@code ParamStateChanged(APPLY_GLOBAL, 全部条目路径)}；目标不可解析或生效参数为空时为
     * no-op（不发布事件、不压撤销记录）。
     */
    void applyGlobalParams(TargetId target, boolean imageMode);

    /** 撤销上一条工作区命令（无可撤销时为 no-op）。 */
    void undo();

    // ---- B5-1：导入编排 ----

    /**
     * 统一导入编排（B5-1）：把导入会话的<b>生命周期与界面等待</b>整体后端化 —— 会话/轮次扫描
     * （{@code mht-import-scan} 后台守护线程）、配额确认往返（经 {@link Confirmer}）、自动建组命名、
     * 撤销压栈（<b>一次导入的每一轮恰好一条</b>，载荷 = 含本轮的全量累计，BC-5）与唯一收尾都在后端；
     * 规则底座为 {@code WorkspaceImportService}（规范化 / 去重 / 条目构造 / 累计 / 组名计算）。
     *
     * <p><b>调用方前置（与迁移前 MainController 一致，不变）</b>：地址已规范化（去重 / 祖先覆盖）、
     * 空地址与导入在途已拦截、拖拽来源盘符根确认（BC-8）已完成；本命令只负责「开始会话 → 发布
     * {@link PortEvent.ImportStateChanged}(importing=true) → 起扫描线程」。前端经
     * {@link PortEvent.ImportRound} / {@link PortEvent.ImportFinished} 事件驱动刷新。</p>
     */
    void importPaths(java.util.List<String> addresses, String sourceDesc, boolean fromDrag);

    /**
     * 分轮导入第二拍（B5-1）：程序化驱动一轮计划（{@link ImportPlanVm}）落地 —— 去重 / 条目构造 /
     * 累计 / 组名规则在 {@code WorkspaceImportService}，模型命令与撤销压栈在后端模型。
     * 无进行中的导入会话时后端按需建一个「空地址」会话（与迁移前控制器长期存在的累计字段等价），
     * 不启动线程、不置位导入标志。本轮落地后发布 {@link PortEvent.ImportRound}。
     */
    void applyImportPlan(ImportPlanVm plan);

    // ---- B6：提取任务通道（矩阵处置项 1）----

    /**
     * 启动提取任务（B6）：deny 链 / 门链 / UI 确认卡在前端（它们渲染卡片），<b>请求构建与任务通道
     * 在后端</b> —— 后端完成「运行时配置 → 会话目录 → 输出单元计划 → 不可变请求快照」并启动
     * worker；此后一切经 {@link PortEvent.ExtractionChannelEvent} 族事件驱动
     * （进度 {@code ExtractionProgress}、终态 {@code ExtractionTerminal}、取消 partial
     * {@code ExtractionResult}）。任务通道契约（每任务一代际、终态恰好一次、取消请求 ≠ worker
     * 已退出、取消后立即再开不互相污染）由后端保证。
     *
     * <p><b>调用方前置（与迁移前 {@code startExtractionTask} 一致，不变）</b>：deny 链与顺序门
     * 已放行、「只提取选中」的旧结果色清理与界面锁定（开始/停止按钮、进度条归零）已完成；
     * 本命令只在宿主串行线程（生产 = FX）调用。</p>
     *
     * @param checkedOnly 是否只提取列表中被勾选的项目（"开始提取"点击时快照）
     */
    void startExtraction(boolean checkedOnly);

    /**
     * 取消在途提取任务（B6；无在途任务或 worker 已收尾时为空操作）：取消请求时刻立即交付
     * {@code ExtractionTerminal(CANCELLED)}（前端据此复位停止/开始按钮），partial 回写经
     * {@code ExtractionResult} 在 worker 收尾后投递一次。在宿主串行线程（生产 = FX）调用。
     */
    void cancelExtraction();

    /**
     * 清空工作区数据序（组随数据序一并清空；撤销栈与组号计数器不动 —— 与后端
     * {@code WorkspaceModel#clearItems()} 的既有清场语义一致）。
     */
    void clearItems();

    /** Stable-ID drop; returns changed state and affected paths after backend postprocessing. */
    default DropVm applyDrop(TargetId dragged, TargetId target, String zone) {
        throw new UnsupportedOperationException("Drop is not wired");
    }

    default void removeItems(java.util.List<String> paths) { throw new UnsupportedOperationException("Removal is not wired"); }
    default void removeGroup(long groupNo) { throw new UnsupportedOperationException("Removal is not wired"); }
}
package com.mhtextractor.uiport;

import com.mhtextractor.model.AppConfig;
import java.util.List;

/**
 * 工作区查询（最小切片）：视图模型快照。
 */
public interface WorkspaceQueries {

    long activityGeneration();
    long previewGeneration();
    /** null 表示没有在途预览。 */
    String previewLoadingPath();

    /**
     * 工作区视图模型快照（一次性不可变；后续变更经 {@link PortEvents} 送达）。
     *
     * @return 快照；无任何条目时返回空集合而非 null
     */
    WorkspaceVm workspace();

    default boolean canUndo() { return workspace().canUndo(); }

    public AppConfig runtimeConfig();

    public List<OutputUnitVm> outputUnitPlan(boolean checkedOnly);

    public ParamSchemaVm paramSchema(boolean imageMode);
}
package com.mhtextractor.uiport;

import java.util.Objects;

/**
 * 列表条目视图模型（不可变 record，自持；不引用任何业务类型）。
 *
 * @param id        条目 id = 文件路径（工作区内的唯一标识）
 * @param name      显示名（文件名）
 * @param checked   勾选状态（提取输入事实；复选框展示语义属前端）
 * @param removed   移除标记（隐藏式移除：不实际从列表删除，仅隐藏并排除在序号/提取名单外）
 * @param unitIndex 输出单元序号（null = 未参与输出单元规划，如已移除条目）
 * @param update    列表动画类别（{@link UpdateKind}）
 */
public record ItemVm(String id, String name, boolean checked, boolean removed,
                     Integer unitIndex, UpdateKind update, String sourceFolder) {

    public ItemVm(String id, String name, boolean checked, boolean removed,
                  Integer unitIndex, UpdateKind update) {
        this(id, name, checked, removed, unitIndex, update, null);
    }

    public ItemVm {
        Objects.requireNonNull(id, "id");
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(update, "update");
    }
}
package com.mhtextractor.uiport;

import java.util.List;
import java.util.Objects;

/**
 * 工作区视图模型快照（一次性不可变 record，自持；不引用任何业务类型）。
 *
 * <p><b>P3-3a 收敛（诚实化）</b>：P3-2 切片中原有的 {@code running} / {@code importing} /
 * {@code lastStats} 已删除 —— 后端当前不能回答它们（提取/导入编排与统计仍在 GUI）。
 * 待能力下沉后加回（P3-3b+）。</p>
 *
 * @param groups        分组列表（含成员，按后端数据序）
 * @param topLevelItems 顶层条目列表（按后端数据序）
 * @param canUndo       是否有可撤销命令
 * @param undoDepth     撤销深度
 * @param selection     勾选三态（{@link TriState}，从条目勾选状态导出）
 */
public record WorkspaceVm(List<GroupVm> groups, List<ItemVm> topLevelItems,
                          boolean canUndo, int undoDepth, TriState selection, List<TargetId> topLevelOrder) {

    public WorkspaceVm(List<GroupVm> groups, List<ItemVm> items, boolean canUndo, int undoDepth, TriState selection) {
        this(groups, items, canUndo, undoDepth, selection,
                java.util.stream.Stream.concat(groups.stream().map(g -> TargetId.ofGroup(g.no())),
                        items.stream().map(i -> TargetId.ofItem(i.id()))).toList());
    }

    public WorkspaceVm {
        groups = List.copyOf(Objects.requireNonNull(groups, "groups"));
        topLevelItems = List.copyOf(Objects.requireNonNull(topLevelItems, "topLevelItems"));
        Objects.requireNonNull(selection, "selection");
        topLevelOrder = List.copyOf(topLevelOrder);
    }
}
package com.mhtextractor.uiport;

import java.util.List;
import java.util.Objects;

/**
 * 分组视图模型（不可变 record，自持；不引用任何业务类型）。
 *
 * @param no           组序号（工作区内唯一）
 * @param name         组名
 * @param expanded     展开状态（后端持有，影响投影与单元规划）
 * @param defaultNamed 是否默认命名（未命名组拦截门判定用）
 * @param members      成员条目（{@link List#copyOf} 防御性不可变拷贝）
 */
public record GroupVm(long no, String name, boolean expanded, boolean defaultNamed,
                      List<ItemVm> members, List<String> sourceFolders) {

    public GroupVm(long no, String name, boolean expanded, boolean defaultNamed, List<ItemVm> members) {
        this(no, name, expanded, defaultNamed, members, members.stream().filter(m -> !m.removed())
                .map(m -> m.sourceFolder() == null || m.sourceFolder().isEmpty() ? null : m.sourceFolder())
                .distinct().toList());
    }

    public GroupVm {
        Objects.requireNonNull(name, "name");
        members = List.copyOf(Objects.requireNonNull(members, "members"));
        sourceFolders = java.util.Collections.unmodifiableList(new java.util.ArrayList<>(sourceFolders));
    }
}

package com.mhtextractor.app;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.model.ParamScope;

/**
 * 参数剪贴板（Q10 / R7.1–R7.7）：右键「复制参数」与「应用到所选」之间的<b>唯一</b>状态载体，
 * 并把一次批量应用收成<b>一条</b> {@code PARAM_SET} 撤销记录。
 *
 * <p><b>这里没有第二套应用逻辑</b>：真正的写入（含缓存失效与撤销压栈）仍是宿主既有的
 * {@code applyItemParams} / {@code applyGroupParams} / {@code applyConfirmedParams} —— 也就是参数配置
 * 界面点「确认」后的那条路径。本类只做三件事：</p>
 * <ol>
 *   <li><b>存快照</b>：只存<b>可持久化提取参数</b>的值快照（{@link AppConfig#copyExtractionParams()}）；
 *       4 个 {@code @JsonIgnore} 运行时/GUI 字段不参与复制、应用时也不覆盖（R7.7）；</li>
 *   <li><b>逐目标复用同一份应用函数</b>：作用域路由与应用本体都由宿主注入（{@link Function} +
 *       {@link ApplyFn}），与本类无关 —— 故"应用到所选"与"点确认"走的是同一份实现（R7.4）；</li>
 *   <li><b>把撤销压栈收成一条</b>：被复用函数本是"每个目标压一条"，批量期间其压栈经
 *       {@link #pushParamUndo} 只累积各目标的 <i>before</i> 快照，整批结束压一条（R7.5）；
 *       单目标应用（点确认 / 右键目标只有一个）粒度不变，仍是一条。</li>
 * </ol>
 *
 * <p><b>纯数据 + 纯编排、零 JavaFX、零模型写入</b>：写入全在宿主，故本类可无头单测。</p>
 */
public final class ParamClipboard {

    /** 应用函数签名：宿主既有的"确认路径应用本体"（{@code applyTargetParams}） */
    @FunctionalInterface
    public interface ApplyFn {
        void apply(ParamScope.Target target, boolean imageMode, AppConfig params);
    }

    /** 作用域路由（选择对象 → 参数作用域目标）：与"设置参数"按钮同一份实现 */
    private final Function<Object, ParamScope.Target> scopeOf;

    /** 应用本体（复用确认路径） */
    private final ApplyFn apply;

    /** 撤销压栈出口（宿主的 {@code WorkspaceModel::push}） */
    private final Consumer<UndoManager.Record<PreviewItem>> undoPush;

    /** 已复制的提取参数快照；{@code null} = 尚未复制过（R7.3） */
    private AppConfig params;

    /** 批量应用标记：非 {@code null} 时处于一次批量应用中（值为该次的模式位） */
    private Boolean batchImageMode;

    /** 批量期间累积的条目级 before 快照（path → 参数） */
    private Map<String, AppConfig> batchItemBefore;

    /** 批量期间累积的组级 before 快照（groupNo → 参数） */
    private Map<Integer, AppConfig> batchGroupBefore;

    public ParamClipboard(Consumer<UndoManager.Record<PreviewItem>> undoPush,
                          Function<Object, ParamScope.Target> scopeOf, ApplyFn apply) {
        this.undoPush = undoPush;
        this.scopeOf = scopeOf;
        this.apply = apply;
    }

    // ==================== 剪贴板状态（R7.3/R7.7） ====================

    /** 是否尚未复制过（「应用到所选」的前置；清空后回到禁用） */
    public boolean isEmpty() {
        return params == null;
    }

    /** 复制一份值快照（源为 {@code null} 视为"无参数、不复制"—— 该情形由 R7.2 的菜单项禁用把关） */
    public void copy(AppConfig source) {
        params = source == null ? null : source.copyExtractionParams();
    }

    /** 取出一份<b>新的</b>快照副本（未复制过 → {@code null}）：每个目标拿到独立实例，避免就地修改串味 */
    public AppConfig snapshot() {
        return params == null ? null : params.copyExtractionParams();
    }

    /** 清空剪贴板（清空后 {@link #isEmpty()} 回到 true） */
    public void clear() {
        params = null;
    }

    /**
     * 复制/应用两项的<b>参数判定快照</b>（R7.2/R7.3/R7.6）：目标集合"是否有生效参数 / 是否统一"的判定
     * 一律经 {@link EffectiveParamsService}（唯一实现，禁止各写一套），本类只做布尔组合；
     * {@code copied} 位就是本剪贴板是否非空（{@link #isEmpty()}）。
     *
     * @param targets     本次"所选"集合（宿主按勾选优先 → 右键目标解析）
     * @param independent 目标是否有独立参数（宿主的既有判定）
     */
    public ParamsInfo paramsInfo(List<Object> targets, boolean independent,
                                 EffectiveParamsService service,
                                 EffectiveParamsService.Context ctx,
                                 int topLevelCount, int distinctGroupCount) {
        return new ParamsInfo(independent,
                service.anyHasEffectiveParams(targets, ctx), service.isUniform(targets, ctx), !isEmpty(),
                topLevelCount, distinctGroupCount);
    }

    // ==================== 批量应用与"整批一条撤销记录"（R7.4/R7.5） ====================

    /**
     * 把剪贴板里的快照应用到全部目标：逐目标经 {@link #scopeOf} 解析作用域、经 {@link #apply} 走确认路径；
     * 整批只压<b>一条</b> {@code PARAM_SET}（各目标 before 快照按 path / groupNo 收进同一记录的载荷）。
     */
    public void applyToSelection(List<Object> targets, boolean imageMode) {
        if (isEmpty() || targets == null || targets.isEmpty()) {
            return;
        }
        batchImageMode = imageMode;
        batchItemBefore = new HashMap<>();
        batchGroupBefore = new HashMap<>();
        try {
            for (Object target : targets) {
                apply.apply(scopeOf.apply(target), imageMode, snapshot());
            }
        } finally {
            batchImageMode = null;
        }
        if (!batchItemBefore.isEmpty() || !batchGroupBefore.isEmpty()) {
            undoPush.accept(recordOf(imageMode, null, null, null, batchItemBefore, batchGroupBefore));
        }
        batchItemBefore = null;
        batchGroupBefore = null;
    }

    /**
     * {@code PARAM_SET} 撤销压栈的<b>唯一出口</b>（宿主三处应用函数都经这里，R7.5）。
     *
     * <p>批量应用期间只把该目标的 <i>before</i> 快照累积进本次批量记录，不单独压栈；其余情形
     * （单目标应用、以及批量期间意外出现的全局作用域）照旧立即压一条 —— 后者在菜单驱动下不可达
     * （所选集合只含条目/组），保留该分支是为了"宁可多一条、也不静默丢一条撤销记录"。</p>
     */
    public void pushParamUndo(boolean imageMode, String path, Integer groupNo, AppConfig before) {
        if (batchImageMode != null && (path != null || groupNo != null)) {
            if (path != null) {
                batchItemBefore.put(path, before);
            } else {
                batchGroupBefore.put(groupNo, before);
            }
            return;
        }
        undoPush.accept(recordOf(imageMode, path, groupNo, before, null, null));
    }

    /**
     * 一条 {@code PARAM_SET} 记录：单目标应用把 {@code path}/{@code groupNo}/{@code before} 三个字段
     * 用作载荷；批量应用把 {@code itemBefore}/{@code groupBefore} 两个映射用作载荷（撤销侧按映射是否
     * 为空区分，见 {@code MainController.onUndoClicked} 的 {@code PARAM_SET} 分支）。
     */
    private static UndoManager.Record<PreviewItem> recordOf(boolean imageMode, String path, Integer groupNo,
                                                            AppConfig before, Map<String, AppConfig> itemBefore,
                                                            Map<Integer, AppConfig> groupBefore) {
        return new UndoManager.Record<>(UndoManager.RecordType.PARAM_SET, List.of(),
                null, -1, List.of(), List.of(), List.of(), List.of(),
                false, null, null, null, imageMode, path, groupNo, before,
                false, itemBefore, groupBefore);
    }
}
package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.GroupItem;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.model.FingerprintEncoder;
import com.mhtextractor.model.ParamScope;

import java.util.ArrayList;
import java.util.List;

/**
 * 生效参数服务（R8-①）：把「当前模式下某目标的生效参数是什么」「一组目标的生效参数是否统一 /
 * 组内是否混合」「目标是否存在独立参数」这三件事收敛为<b>全仓库唯一实现点</b>。
 *
 * <p><b>本类零 JavaFX、零第三方依赖、不调 {@code I18n.get}</b>：它只读参数缓存与模型字段，
 * 不产用户文案（{@code app} 层由 {@code ArchitectureTest} 强制）。</p>
 *
 * <h2>为什么是无状态 + 显式 {@link Context}（而不是直接持有 GUI 控件）</h2>
 * <p>两个全局参数缓存（{@code textParamsCache} / {@code imageParamsCache}）在 GUI 侧是<b>可变字段</b>
 * （参数确认 / 应用到全局 / 撤销都会整体替换它们，见 {@code MainController}）。若让本服务持有
 * 这两个引用，就必须处理"换模式、参数被替换后服务读到陈旧值"的问题，且服务会被钉在 GUI 生命周期上。</p>
 * <p>因此本服务<b>不持有任何可变状态</b>：模式与两个全局缓存由调用方每次经 {@link Context} 传入
 * （本质是两个缓存的<b>快照</b> + 一个模式位）。这样服务是纯函数式的、可由测试直接驱动，
 * 而 GUI 侧的"从控件取当前值"这件事收敛到 {@code MainController.effectiveContext()} 一处。</p>
 *
 * <h2>参数解析必须经 {@link ParamScope}（不得绕过、不得复制）</h2>
 * <p>图片模式的生效参数解析必须且只能经 {@link ParamScope#effectiveImageParams} —— 预览落盘与提取
 * （{@code OutputUnitPlanner.resolve}）解析出同一套参数是缓存复用（P10）的前提。本类不复制该逻辑，
 * 只做「按目标类型取出三个候选值 → 交给 {@code ParamScope}」的适配。</p>
 *
 * <h2>值语义口径（"是否统一"怎么比）</h2>
 * <p>{@link AppConfig} 是 Lombok {@code @Data} 可变对象，其 javadoc 明确禁止用 {@code equals} 当
 * 判定键（值会随外部修改而变化）。故本类<b>不调用 {@code equals}</b>，而是把每个配置渲染成
 * <b>字段级内容签名</b>（固定字段顺序 + 长度前缀编码，见 {@link #signatureOf}），再比签名是否相同。
 * 这与 {@code AppConfig.imageExtractionFingerprint()} 是同一套"固定顺序 + 长度前缀"编码风格，
 * 但<b>覆盖范围不同且更宽</b>：</p>
 * <ul>
 *   <li>{@code imageExtractionFingerprint()} 是<b>缓存命中</b>口径，只含影响"提取出哪些图片"的 8 个字段
 *       （P2 明确排除归档与内存模式）；</li>
 *   <li>本类的签名是<b>用户感知</b>口径，覆盖全部用户可设置参数 —— 包括
 *       {@code enableZipPackaging} / {@code enableCbzPackaging} / {@code highSpeedMemoryMode}，
 *       以及文本模式的全部字段。理由：R7 的判据是"多选后存在多个不同生效参数 → 禁用复制/应用"，
 *       用户看到的是"这些设置不一样"，而不是"缓存能不能复用"。</li>
 *   <li>仅排除 4 个<b>非"用户设置的提取参数"</b>的字段：{@code inputFolder} / {@code outputFolder} /
 *       {@code openFolderAfterComplete}（GUI 运行时状态；前两者属 {@code gui-state.json}）与
 *       {@code imageModeEnabled}（{@code AppConfig} javadoc 明写"提取模式属于主窗口 GUI 状态，
 *       运行时由主窗口模式开关写入"—— 它标的是"当前在哪个模式"，而"是否统一"本就只在单一模式内比较）。</li>
 * </ul>
 * <p>签名是 {@code imageExtractionFingerprint()} 的<b>超集</b>：图片模式下签名相同 ⇒ 指纹必然相同
 * （反之不成立），故"统一"判定比"缓存可复用"判定更严格 —— 不会出现"判定为统一却各自缓存不命中"
 * 的不一致方向（该方向才是危险的）。</p>
 */
public final class EffectiveParamsService {

    /** 无生效参数的固定标记（真实签名至少含一个模式位字符，故与任何真实签名都不同） */
    public static final String NO_PARAMS = "<none>";

    /**
     * 一次判定所需的参数解析上下文：当前是否图片模式 + 该模式与另一模式的全局已确认参数缓存
     * （{@code null} = 该模式尚未确认过参数）。
     *
     * <p>不可变快照：调用方在每次判定前重新构造即可（GUI 侧 {@code MainController.effectiveContext()}）。</p>
     */
    public record Context(boolean imageMode, AppConfig textGlobal, AppConfig imageGlobal) {
    }

    /**
     * 生效参数（唯一入口）：
     * <ul>
     *   <li>{@link GroupItem} → 只按组解析（组 &gt; 全局）—— 条目级参数与组目标无关；</li>
     *   <li>{@link PreviewItem} → 三层覆盖：{@code parentGroup} 的组参数 &gt; 条目级参数 &gt; 全局；</li>
     *   <li>null / 其他类型 → {@code null}（无生效参数）。</li>
     * </ul>
     *
     * <p>图片模式经 {@link ParamScope#effectiveImageParams}、文本模式经
     * {@link ParamScope#effectiveParams} —— 与迁移前 {@code MainController.effectiveForObject}
     * 的解析路径<b>逐语义等价</b>（同一个 {@code ParamScope} 分支，不再保留第二份）。</p>
     */
    public AppConfig effectiveFor(Object target, Context ctx) {
        GroupItem<?> parent = null;
        AppConfig itemText = null;
        AppConfig itemImage = null;
        if (target instanceof PreviewItem it) {
            parent = it.parentGroup;
            itemText = it.textItemParams;
            itemImage = it.imageItemParams;
        } else if (target instanceof GroupItem<?> g) {
            parent = g;
        }
        return ctx.imageMode()
                ? ParamScope.effectiveImageParams(parent, itemImage, ctx.imageGlobal())
                : ParamScope.effectiveParams(parent, itemText, itemImage, false,
                        ctx.textGlobal(), ctx.imageGlobal());
    }

    /**
     * 生效参数的来源状态（{@link ParamScope.Status}）：{@code GROUP} = 存在独立参数
     * （组参数或条目级参数），{@code GLOBAL} = 生效参数就是全局参数，{@code NONE} = 无生效参数。
     *
     * <p>这是 {@link #hasIndependentParams} 的原始形态，供视图层需要三态（而不仅二态）时使用。</p>
     */
    public ParamScope.Status effectiveSourceOf(Object target, Context ctx) {
        GroupItem<?> parent = target instanceof PreviewItem it ? it.parentGroup
                : (target instanceof GroupItem<?> g ? g : null);
        AppConfig itemText = target instanceof PreviewItem it ? it.textItemParams : null;
        AppConfig itemImage = target instanceof PreviewItem it ? it.imageItemParams : null;
        return ParamScope.backgroundStatus(parent, itemText, itemImage, ctx.imageMode(),
                ctx.textGlobal(), ctx.imageGlobal());
    }

    /**
     * 目标是否存在<b>独立参数</b>（组参数或条目级参数）—— 即拍板语义"仅此状态『应用到全局』可用"。
     *
     * <p>等价于 {@code effectiveSourceOf(target, ctx) == ParamScope.Status.GROUP}；单留一个实现点
     * （本方法委托 {@link #effectiveSourceOf}），故视图层的"清除参数"/"应用到全局"启用判定与
     * 背景色三态判定<b>共用同一份来源判定</b>，不会再各自演化。</p>
     */
    public boolean hasIndependentParams(Object target, Context ctx) {
        return effectiveSourceOf(target, ctx) == ParamScope.Status.GROUP;
    }

    /**
     * 一组目标的生效参数是否<b>混合</b>（存在多种取值）。
     *
     * <p><b>判定口径（本步明确决定）：{@code null}（无生效参数）算作一种独立取值</b> ——
     * {@code [A, null]} 视为混合。理由：用户在多选列表里看到的确实是"不统一"（一部分条目有参数、
     * 一部分没有），而 R7 的动作是"存在多个不同生效参数 → 禁用复制/应用参数"。若把 {@code null}
     * 忽略，则"一半有参数一半没有"会被判为统一，进而允许把参数复制到无参数条目上 —— 与"复制"的
     * 用户预期相反。</p>
     *
     * <p>边界：<b>空列表与单元素列表均为"不混合"</b>（0 或 1 种取值）。</p>
     */
    public boolean hasMixedEffectiveParams(List<?> targets, Context ctx) {
        if (targets == null || targets.size() < 2) {
            return false;
        }
        // 用有序列存已见签名（选择集规模是"同组/同选择集"，元素极少）：
        // 必须能区分 null 与"某套参数"，故 NO_PARAMS 作为一个独立取值参与去重。
        List<String> seen = new ArrayList<>();
        for (Object target : targets) {
            String sig = signatureOf(effectiveFor(target, ctx));
            if (!seen.contains(sig)) {
                seen.add(sig);
                if (seen.size() > 1) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * 一组目标的生效参数是否<b>统一</b>（{@code !hasMixedEffectiveParams}，只此一个实现点）。
     *
     * <p>边界（与 {@link #hasMixedEffectiveParams} 一致）：空列表与单元素列表均为统一。</p>
     */
    public boolean isUniform(List<?> targets, Context ctx) {
        return !hasMixedEffectiveParams(targets, ctx);
    }

    /** 任一目标存在生效参数（非 null）。空列表 → {@code false}。 */
    public boolean anyHasEffectiveParams(List<?> targets, Context ctx) {
        if (targets == null) {
            return false;
        }
        for (Object target : targets) {
            if (effectiveFor(target, ctx) != null) {
                return true;
            }
        }
        return false;
    }

    /** 全部存在生效参数的目标（保持输入顺序）；供"参数目标信息栏"等展示用途。 */
    public List<Object> targetsWithEffectiveParams(List<?> targets, Context ctx) {
        List<Object> out = new ArrayList<>();
        if (targets != null) {
            for (Object target : targets) {
                if (effectiveFor(target, ctx) != null) {
                    out.add(target);
                }
            }
        }
        return out;
    }

    // ==================== 值语义：字段级内容签名 ====================

    /**
     * 配置的字段级内容签名（{@code null} → 固定标记 {@link #NO_PARAMS}）。
     *
     * <p>固定字段顺序 + 字符串长度前缀编码，不依赖 Map/Set 迭代顺序、不依赖 Lombok 生成顺序，
     * 且<b>不用 {@code equals}/{@code toString}/反射</b> —— 新增字段时签名会变（这正是我们要的：
     * 新参数一旦影响行为就必须参与"是否统一"判定），而不是静默沿用旧判定。
     * {@code AppConfigTest} 有一条"字段守护"用例会提醒同步本方法。</p>
     */
    public static String signatureOf(AppConfig c) {
        if (c == null) {
            return NO_PARAMS;
        }
        StringBuilder sb = new StringBuilder(256);
        // 通用
        sb.append(c.isSeparateFiles() ? '1' : '0');
        // 文本提取
        sb.append(c.isEnableContentLimit() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getEndMarker());
        sb.append(c.isUseRegex() ? '1' : '0');
        sb.append(c.isEnableTemplate() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getStartTemplate());
        FingerprintEncoder.lengthPrefixed(sb, c.getEndTemplate());
        sb.append(c.isAddChapterNumber() ? '1' : '0');
        sb.append(c.isAutoFixEncoding() ? '1' : '0');
        sb.append(c.isEnableTitleExtraction() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getTitleStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getTitleEndMarker());
        sb.append(c.isTitleUseRegex() ? '1' : '0');
        // 图片提取
        sb.append(c.isEnableNameExtraction() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getImageNameStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getImageNameEndMarker());
        sb.append(c.isEnableRegionExtraction() ? '1' : '0');
        FingerprintEncoder.lengthPrefixed(sb, c.getImageRegionStartMarker());
        FingerprintEncoder.lengthPrefixed(sb, c.getImageRegionEndMarker());
        sb.append(c.isEnableBatchRenaming() ? '1' : '0');
        sb.append(c.isEnableZipPackaging() ? '1' : '0');
        sb.append(c.isEnableCbzPackaging() ? '1' : '0');
        sb.append(c.isSingleOutputMode() ? '1' : '0');
        // 处理模式
        sb.append(c.isHighSpeedMemoryMode() ? '1' : '0');
        // 兼容旧版废弃字段（保留反序列化兼容；仍参与判定，避免"设置里看得见却不影响判定"）
        FingerprintEncoder.lengthPrefixed(sb, c.getNameLimitStart());
        FingerprintEncoder.lengthPrefixed(sb, c.getNameLimitEnd());
        FingerprintEncoder.lengthPrefixed(sb, c.getContentLimitStart());
        FingerprintEncoder.lengthPrefixed(sb, c.getContentLimitEnd());
        return sb.toString();
    }

    /**
     * 仅供签名一致性守护测试使用：本签名刻意排除的 AppConfig 字段
     * （纯运行时/GUI 状态，不属于"用户设置的提取参数"）。
     *
     * <p>返回<b>不可变副本</b>，避免测试或调用方改动内部集合。</p>
     */
    public static List<String> runtimeOnlyFields() {
        return List.copyOf(RUNTIME_ONLY_FIELDS);
    }

    private static final List<String> RUNTIME_ONLY_FIELDS =
            List.of("inputFolder", "outputFolder", "imageModeEnabled", "openFolderAfterComplete");
}
package com.mhtextractor.app;

import com.mhtextractor.core.MimeParser;
import com.mhtextractor.core.SourceParsers;
import com.mhtextractor.util.HtmlExportBuilder;

import java.io.IOException;
import java.nio.file.Path;

/**
 * 「在浏览器查看 HTML」的解析 + 导出段（P3-3b-4）：从 {@code gui.controller.SourceViewActions}
 * 的 {@code openHtmlInBrowser} 后台线程原样下沉到 app 层 —— 解析入口
 * （{@code SourceParsers.forPath(path)}）、解析参数（{@code textOnly=false}、三回调
 * {@code () -> false / null / null}）、空 HTML 判定与 {@code HtmlExportBuilder.export} 调用
 * 逐条照搬搬迁前的 :86-94（只搬不改）。
 *
 * <p>本类<b>零 JavaFX、零 I18n</b>，不产任何展示文案：解析无 HTML / 导出失败经
 * {@link Export#Unparseable()} / {@link Export#Failed(String)} 表达，
 * 文案键与日志键仍由 gui 层按原键渲染。</p>
 *
 * <p>本类属 {@code app} 层。</p>
 */
public final class SourceViewService {

    private SourceViewService() {
    }

    /** 解析 + 导出的三种结果（sealed，调用方穷举切换；对应搬迁前原代码的三种走向）。 */
    public sealed interface Export {
        /** 导出成功：html 文件路径 + 图片数与警告数（搬迁前 {@code HtmlExportBuilder.ExportResult} 的同名口径）。 */
        record Success(Path htmlFile, int imageCount, int warningCount) implements Export {
        }

        /** 解析所得内容没有 HTML（搬迁前：抛 {@code IllegalStateException(browser.exportUnparseable)}）。 */
        record Unparseable() implements Export {
        }

        /** 导出器自身报告失败（搬迁前：抛 {@code IllegalStateException(r.error())}）。 */
        record Failed(String error) implements Export {
        }
    }

    /**
     * 解析 + 导出（与搬迁前 {@code SourceViewActions} :86-94 逐字同义）：
     * {@code SourceParsers.forPath(path).parse(path, false, () -> false, null, null)}
     * → htmlContent 为 null ⇒ {@link Export.Unparseable}；否则
     * {@code HtmlExportBuilder.export(path, parsed)} → 未成功 ⇒ {@link Export.Failed(r.error())}；
     * 成功 ⇒ {@link Export.Success(r.htmlFile(), r.imageCount(), r.warnings().size())}。
     *
     * @param path 来源路径（绝对或相对；按扩展名选 MHT / HTML 解析器）
     * @throws IOException 解析阶段的 IO 异常<b>原样上抛</b>（搬迁前由调用方外层
     *         {@code catch (Exception)} 承接，异常语义不变）
     */
    public static Export export(String path) throws IOException {
        MimeParser.ParsedMht parsed = SourceParsers.forPath(path).parse(path, false, () -> false, null, null);
        if (parsed.getHtmlContent() == null) {
            return new Export.Unparseable();
        }
        HtmlExportBuilder.ExportResult r = HtmlExportBuilder.export(path, parsed);
        if (!r.success()) {
            return new Export.Failed(r.error());
        }
        return new Export.Success(r.htmlFile(), r.imageCount(), r.warnings().size());
    }
}
